package upgrade

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"
)

const defaultGitHubAPIBase = "https://api.github.com/repos/entireio/cli"
const githubAPIBaseEnv = "ENTIRE_UPGRADE_GITHUB_API_BASE_URL"
const defaultReleaseFetchTimeout = 30 * time.Second
const githubReleasePageSize = 100
const githubUserAgent = "entire-upgrade"
const maxErrorBodyBytes = 4096
const maxReleaseJSONBytes = 4 << 20

type ReleaseChecker struct {
	BaseURL string
	Client  *http.Client
}

func (c ReleaseChecker) Latest(ctx context.Context, channel Channel) (Version, error) {
	switch channel {
	case StableChannel:
		return c.latestStable(ctx)
	case NightlyChannel:
		return c.latestNightly(ctx)
	default:
		return Version{}, fmt.Errorf("unsupported release channel %q", channel)
	}
}

func (c ReleaseChecker) latestStable(ctx context.Context) (Version, error) {
	var release struct {
		TagName string `json:"tag_name"`
	}
	if err := c.fetchJSON(ctx, "/releases/latest", &release); err != nil {
		return Version{}, err
	}
	if release.TagName == "" {
		return Version{}, fmt.Errorf("latest stable release did not include a tag name")
	}
	return ParseVersion(release.TagName)
}

func (c ReleaseChecker) latestNightly(ctx context.Context) (Version, error) {
	var latest Version
	for page := 1; ; page++ {
		var releases []struct {
			TagName string `json:"tag_name"`
		}
		path := fmt.Sprintf("/releases?per_page=%d&page=%d", githubReleasePageSize, page)
		if err := c.fetchJSON(ctx, path, &releases); err != nil {
			return Version{}, err
		}

		for _, release := range releases {
			version, err := ParseVersion(release.TagName)
			if err != nil || !version.IsNightly() {
				continue
			}
			if !latest.Present || version.Compare(latest) > 0 {
				latest = version
			}
		}
		if len(releases) < githubReleasePageSize {
			break
		}
	}
	if !latest.Present {
		return Version{}, fmt.Errorf("no nightly release found")
	}
	return latest, nil
}

func (c ReleaseChecker) fetchJSON(ctx context.Context, path string, out any) error {
	base := c.BaseURL
	if base == "" {
		base = os.Getenv(githubAPIBaseEnv)
	}
	if base == "" {
		base = defaultGitHubAPIBase
	}
	base = strings.TrimRight(base, "/")
	client := c.Client
	if client == nil {
		client = &http.Client{Timeout: defaultReleaseFetchTimeout}
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, base+path, nil)
	if err != nil {
		return err
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", githubUserAgent)
	if token := os.Getenv("GITHUB_TOKEN"); token != "" && shouldSendGitHubToken(req.URL) {
		req.Header.Set("Authorization", "Bearer "+token)
	}

	resp, err := client.Do(req)
	if err != nil {
		return fmt.Errorf("fetch Entire CLI releases: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, maxErrorBodyBytes))
		if message := strings.TrimSpace(string(body)); message != "" {
			return fmt.Errorf("fetch Entire CLI releases: GitHub returned %s: %s", resp.Status, message)
		}
		return fmt.Errorf("fetch Entire CLI releases: GitHub returned %s", resp.Status)
	}
	if err := json.NewDecoder(io.LimitReader(resp.Body, maxReleaseJSONBytes)).Decode(out); err != nil {
		return fmt.Errorf("decode Entire CLI release response: %w", err)
	}
	return nil
}

func shouldSendGitHubToken(u *url.URL) bool {
	return strings.EqualFold(u.Hostname(), "api.github.com")
}

